import{_ as i,l as o,o as e,c as p,v as l,p as n,x as r,d as s,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"熵塌缩与熵正则","description":"","frontmatter":{"title":"熵塌缩与熵正则","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/entropy-collapse.md","filePath":"llm/entropy-collapse.md","lastUpdated":1789023840000}'),c={name:"llm/entropy-collapse.md"};function E(m,a,A,_,u,B){const t=o("Mermaid");return e(),p("div",null,[a[1]||(a[1]=l('<h1 id="熵塌缩与熵正则" tabindex="-1">熵塌缩与熵正则 <a class="header-anchor" href="#熵塌缩与熵正则" aria-label="Permalink to &quot;熵塌缩与熵正则&quot;">​</a></h1><div class="epigraph"><p>组内回复互为复制时，相对优势消失；熵不是装饰项，是群体方法还能否学习的前提。</p><footer>—— 对照 DAPO 用熵曲线诊断 clip；Schulman PPO 可选的熵奖励；R1 训练中的探索依赖采样温度</footer></div><p><a href="/llm/length-normalization-bias">上一课</a>把长而重复的链部分归因于损失测度。更常见的死因是：<strong>策略熵塌到近零，温度 1 也采不出新轨迹。</strong> 本课写塌缩的机制与熵正则，以及为何 Clip-Higher、温度、KL 都在抢同一条探索预算。不重推 <a href="/llm/ppo-llm">PPO</a> clip。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/grpo">GRPO</a> 需要组内 \\(r_i\\) 有方差。熵塌后，\\(G\\) 条完成几乎相同，全对或全错，优势为零。DAPO 把朴素复现停在 AIME 30 分的第一条诊断写成熵崩溃。PPO 有 critic，仍需要探索才能见到新的高奖励完成。熵正则 \\(+\\alpha H(\\pi(\\cdot\\mid s))\\) 是古典补丁，但 \\(\\alpha\\) 过大会变成胡言，过小则挡不住塌缩。</p><p>塌缩的驱动：对称 clip 卡住低频词、KL 把策略钉在短答 SFT、学习率过大一步把分布拧尖、重复惩罚在训练期缺失。只加熵项而不改 clip / KL，常常失败。</p><h3 id="监控哪一种熵" tabindex="-1">监控哪一种熵 <a class="header-anchor" href="#监控哪一种熵" aria-label="Permalink to &quot;监控哪一种熵&quot;">​</a></h3><p>应对回答段的平均逐 token 熵，而不是含提示的序列熵。还要看组内独特 n-gram 率、平均编辑距离。熵数字还行但组内互抄，说明条件熵在「同一题」上塌了，无条件熵被题间差异撑住。</p><p><span class="marginnote">评测温度 0 与训练熵不是一回事。训练必须保持探索；评测可以 greedy。不要用评测准确率下降反推「熵太大」而不看训练曲线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先结构性放探索：Clip-Higher、足够温度（后课）、去掉或减小对参考的 KL（推理 RL）。再考虑 \\(\\alpha H\\)。\\(\\alpha\\) 可按目标熵做 PID：低于阈值加大，高于则关。不要与逐步 KL 的 \\(\\beta\\) 对着加——一个拉向参考，一个推开，净效果不明。可验证域参考分布往往是短 SFT，KL 本身在制造塌缩。</p>',11)),(e(),n(d,null,{default:r(()=>[h(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20COL%5B%22%E7%86%B5%E5%A1%8C%20%2F%20%E7%BB%84%E5%86%85%E5%A4%8D%E5%88%B6%22%5D%20--%3E%20C%5B%22Clip-Higher%22%5D%0A%20%20COL%20--%3E%20T%5B%22%E6%8F%90%E9%AB%98%E9%87%87%E6%A0%B7%E6%B8%A9%E5%BA%A6%22%5D%0A%20%20COL%20--%3E%20KL%5B%22%E5%87%8F%E5%B0%8F%E6%88%96%E5%8E%BB%E6%8E%89%20KL%22%5D%0A%20%20COL%20--%3E%20H%5B%22%E7%86%B5%E5%A5%96%E5%8A%B1%20%CE%B1H%22%5D%0A%20%20C%20--%3E%20VAR%5B%22%E7%BB%84%E5%86%85%20r%20%E6%96%B9%E5%B7%AE%E6%81%A2%E5%A4%8D%22%5D%0A%20%20T%20--%3E%20VAR%0A%20%20KL%20--%3E%20VAR%0A%20%20H%20--%3E%20VAR%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>重复 n-gram 惩罚可当塑形，但会改变最优语言；优先当诊断，而不是长期写进 \\(R\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>熵是局部随机性。任务需要的探索往往是<strong>语义分叉</strong>（换证法），不是每个 token 都均匀。\\(\\alpha H\\) 鼓励后者，可能加长胡话。Clip-Higher 针对「罕见高优势 token」放行，更接近语义分叉。这就是 DAPO 把 clip 放在熵项前面的原因。R1-Zero 能长出反思，依赖的是可验证奖励下的采样多样性，而不是大 \\(\\alpha\\)。</p><p><span class="marginnote">全对组熵可以不低（都在正确写法里换词），但优势仍为零。熵是必要条件不是充分条件；动态采样处理的是后者。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>开放偏好上高熵会伤害流畅，产品更怕胡言。推理竞赛更怕塌缩。\\(\\alpha\\) 不能跨域抄。下一课过长过滤处理的是另一头：探索变成无尽重复直到截断。熵与长度要同图看：长度涨、熵掉，多半是重复；长度涨、熵稳，才像真在搜索。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>熵塌导致组内无相对信号，群体 RL 停止学习。</li><li>先改 clip / 温度 / KL，再加 \\(\\alpha H\\)；熵项鼓励的是局部随机而非语义分叉。</li><li>监控回答段熵与组内独特率，不要只看含提示的数。</li><li>熵必要、不够；全对全错仍要动态采样。</li><li>出处：Yu 等 DAPO；Schulman PPO 熵奖励；Shao / DeepSeek-AI 的探索实践。</li></ul>',8))])}const g=i(c,[["render",E]]);export{f as __pageData,g as default};
